import { normalizeLegacy } from "./legacy";

export type Provider = "modern" | "beta" | "legacy";

export function normalizeProvider(provider: Provider) {
  if (provider === "legacy") {
    return normalizeLegacy(provider);
  }
  if (provider === "beta") {
    return "beta";
  }
  return "modern";
}
